#[cfg(test)]
mod tests {
    use super::*;

    /// The proof bundled at export time verifies against the embedded VK, with
    /// its public inputs and only with them.
    #[test]
    fn bundled_proof_verifies() {
        let proof = Proof::from_le_bytes(include_bytes!("../proof.solana.bin"));
        let mut fields: Fields = [[0; 32]; NUM_PUBLIC_INPUTS];
        for (f, b) in fields
            .iter_mut()
            .zip(include_bytes!("../public_inputs.solana.bin").chunks(32))
        {
            f.copy_from_slice(b);
        }
        assert!(verify(&proof, fields));
        if let Some(first) = fields.first_mut() {
            first[0] ^= 1;
            assert!(!verify(&proof, fields));
        }
    }

    /// The sample's public inputs, by name, are its field elements, and verify.
    #[test]
    fn typed_public_inputs_match_the_sample() {
        let inputs = PublicInputs {
            commitment: [0x17, 0xc9, 0x28, 0x5d, 0x44, 0x83, 0x6d, 0x64, 0x78, 0xd6, 0x0a, 0xea, 0x11, 0x33, 0x77, 0xaf, 0xcc, 0x42, 0x6b, 0x61, 0x9a, 0xe7, 0x6b, 0xe0, 0x96, 0xf0, 0x6e, 0x5d, 0xd2, 0x94, 0xbc, 0x21],
            policy: Policy { today: <Days<1900, 2100>>::from_steps(46315).unwrap(), born_by: <Days<1900, 2100>>::from_steps(39741).unwrap(), min_net_worth: 500000, allowed: Bitfield::<Country>::EMPTY.with(Country::DE).with(Country::FR).with(Country::GB).with(Country::US), },
            holder: [0x07, 0x07, 0x07, 0x07, 0x07, 0x07, 0x07, 0x07, 0x07, 0x07, 0x07, 0x07, 0x07, 0x07, 0x07, 0x07, 0x07, 0x07, 0x07, 0x07, 0x07, 0x07, 0x07, 0x07, 0x07, 0x07, 0x07, 0x07, 0x07, 0x07, 0x07, 0x07],
        };
        let fields: Vec<[u8; 32]> = include_bytes!("../public_inputs.solana.bin")
            .chunks(32)
            .map(|c| c.try_into().unwrap())
            .collect();
        assert_eq!(inputs.to_fields().as_slice(), fields.as_slice());
        let proof = Proof::from_le_bytes(include_bytes!("../proof.solana.bin"));
        assert!(verify(&proof, inputs));
    }
}
